script:
frappe.ui.form.on('Hostel Registration', {
    refresh(frm) {
        if (frm.doc.status === 'Approved' && !frm.doc.allocated_room) {
            frm.add_custom_button(__('Allocate Room'), function() {
                frappe.new_doc('Hostel Allocation', {
                    registration: frm.doc.name,
                    hostel: frm.doc.preferred_hostel,
                    room_type: frm.doc.preferred_room_type,
                    from_date: frappe.datetime.get_today()
                });
            }, __('Actions'));
        }
    }
});
